# Rows of the SymPy ODE test files (test_single.py, test_ode.py,
# test_systems.py, test_riccati.py, test_lie_group.py) and the dsolve
# documentation examples, each compared with the str() of SymPy's result.

.odetest_fmt_in <- function(v) if (is.character(v) && length(v) == 1L && is.null(attr(v, "tuple"))) paste0("'", v, "'") else .odetest_fmt(v)
.odetest_fmt <- function(v) {
  if (is.null(v)) return("None")
  if (inherits(v, "condition")) return(paste0(.odetest_err_class(v), "(", conditionMessage(v), ")"))
  if (inherits(v, "ode_solver")) return(paste0("<", v$name, ">"))
  if (inherits(v, "pytuple")) {
    s <- vapply(v, .odetest_fmt_in, "")
    return(paste0("(", paste(s, collapse = ", "), if (length(s) == 1L) ",", ")"))
  }
  if (inherits(v, "pydict")) {
    if (!length(v$keys)) return("{}")
    kf <- function(k) if (is.character(k) && length(k) == 1L) paste0("'", k, "'") else .odetest_fmt(k)
    ix <- seq_along(v$keys)
    if (all(vapply(v$keys, is.character, TRUE))) ix <- order(unlist(v$keys), method = "radix")
    return(paste0("{", paste(vapply(ix, function(i)
      paste0(kf(v$keys[[i]]), ": ", .odetest_fmt_in(v$values[[i]])), ""), collapse = ", "), "}"))
  }
  if (isTRUE(attr(v, "pyset"))) return(paste0("{", paste((function(s) s[order(gsub("^", "**", s, fixed = TRUE), method = "radix")])(vapply(v, .odetest_fmt, "")), collapse = ", "), "}"))
  if (inherits(v, "symmatrix")) return(.fmt_mat(v))
  if (inherits(v, "sym")) return(sstr(v))
  if (inherits(v, "Poly")) return(paste(utils::capture.output(print(v)), collapse = " "))
  if (is.character(v)) {
    if (!length(v)) return("()")
    s <- paste0("'", v, "'")
    return(paste0("(", paste(s, collapse = ", "), if (length(s) == 1L) ",", ")"))
  }
  if (is.logical(v) && length(v) == 1L) return(if (is.na(v)) "None" else if (v) "True" else "False")
  if (is.numeric(v) && length(v) == 1L) return(format(v))
  if (is.list(v) && !is.object(v)) {
    nm <- names(v)
    if (length(v) && !is.null(nm) && all(nzchar(nm)))
      return(paste0("{", paste(vapply(seq_along(v), function(i) paste0(nm[i], ": ", .odetest_fmt(v[[i]])), ""),
                               collapse = ", "), "}"))
    return(paste0("[", paste(vapply(v, .odetest_fmt_in, ""), collapse = ", "), "]"))
  }
  paste(format(v), collapse = " ")
}

# MatrixBase._format_str, with the column widths of the Python strings
.fmt_mat <- function(M) {
  nr <- M$nrow; nc <- M$ncol
  if (nr == 0L || nc == 0L) return(sprintf("Matrix(%d, %d, [])", nr, nc))
  s <- matrix(vapply(M$data, sstr, ""), nr, nc, byrow = TRUE)
  np <- matrix(nchar(gsub("^", "**", s, fixed = TRUE)), nr, nc)
  w <- apply(np, 2L, max)
  rows <- vapply(seq_len(nr), function(i) paste0("[", paste(paste0(strrep(" ", w - np[i, ]), s[i, ]), collapse = ", "), "]"), "")
  if (nr == 1L) paste0("Matrix([", rows, "])") else paste0("Matrix([\n", paste(rows, collapse = ",\n"), "])")
}

.odetest_err_class <- function(e) {
  cl <- setdiff(class(e), c("simpleError", "error", "condition", "sympy_error"))
  if (length(cl)) cl[1L] else "Error"
}

.odetest <- function(code) {
  v <- tryCatch(eval(parse(text = code), envir = new.env(parent = globalenv())), error = function(e) e)
  s <- if (inherits(v, "error")) paste0("ERR ", .odetest_err_class(v), ": ", conditionMessage(v)) else .odetest_fmt(v)
  .odetest_dummies(gsub("\n", "\\n", gsub("**", "^", s, fixed = TRUE), fixed = TRUE))
}

# Dummy symbols are numbered by a global counter: number them by first appearance
.odetest_dummies <- function(s) {
  m <- regmatches(s, gregexpr("_Dummy_[0-9]+", s))[[1L]]
  u <- unique(m)
  for (k in seq_along(u)) s <- gsub(paste0(u[k], "(?![0-9])"), paste0("_Dummy_@", k - 1L), s, perl = TRUE)
  gsub("_Dummy_@", "_Dummy_", s, fixed = TRUE)
}

test_that("ode test_constant_mul", {
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"y\")), list(Symbol(\"C1\")))"), "C1*y")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"x\")), list(Symbol(\"C1\")))"), "C1*x")
  expect_equal(.odetest("constantsimp((Integer(2)*Symbol(\"C1\")), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"x\")*Symbol(\"y\")), list(Symbol(\"C1\"), Symbol(\"y\")))"), "C1*x")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"y\")*(Integer(1) + Symbol(\"y\"))), list(Symbol(\"C1\")))"), "C1*y*(y + 1)")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"x\")*Symbol(\"y\")), list(Symbol(\"C1\")))"), "C1*x*y")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"y\")*(Integer(1) + Symbol(\"y\"))), list(Symbol(\"C1\"), Symbol(\"y\")))"), "C1")
  expect_equal(.odetest("constantsimp((Integer(2)*Symbol(\"C1\")*(Symbol(\"x\"))^(Integer(2))*(Symbol(\"y\"))^(Integer(2))), list(Symbol(\"C1\"), Symbol(\"y\")))"), "C1*x^2")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"x\")*Symbol(\"y\")*Symbol(\"z\")), list(Symbol(\"C1\"), Symbol(\"y\"), Symbol(\"z\")))"), "C1*x")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"x\")*(Symbol(\"y\"))^(Integer(2))*sin(Symbol(\"z\"))), list(Symbol(\"C1\"), Symbol(\"y\"), Symbol(\"z\")))"), "C1*x")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\"))^(Integer(2)), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"C2\")), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C1")
  expect_equal(.odetest("constantsimp((Symbol(\"C2\"))^(Integer(2)), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C2")
  expect_equal(.odetest("constantsimp((Symbol(\"C2\")*(Symbol(\"C1\"))^(Integer(2))), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C1")
  expect_equal(.odetest("constantsimp((Symbol(\"C1\")*Symbol(\"x\")*(Integer(2))^(Symbol(\"x\"))), list(Symbol(\"C1\")))"), "2^x*C1*x")
})

