test_that("ode test_constant_power_as_exp", {
  expect_equal(.odetest("constantsimp((Symbol(\"x\"))^(Symbol(\"C1\")), list(Symbol(\"C1\")))"), "x^C1")
  expect_equal(.odetest("constantsimp((Symbol(\"y\"))^(Symbol(\"C1\")), list(Symbol(\"C1\"), Symbol(\"y\")))"), "C1")
  expect_equal(.odetest("constantsimp((Symbol(\"x\"))^((Symbol(\"y\"))^(Symbol(\"C1\"))), list(Symbol(\"C1\"), Symbol(\"y\")))"), "x^C1")
  expect_equal(.odetest("constantsimp(((Symbol(\"x\"))^(Symbol(\"y\")))^(Symbol(\"C1\")), list(Symbol(\"C1\")))"), "(x^y)^C1")
  expect_equal(.odetest("constantsimp((Symbol(\"x\"))^((Symbol(\"C1\"))^(Symbol(\"y\"))), list(Symbol(\"C1\"), Symbol(\"y\")))"), "x^C1")
  expect_equal(.odetest("constantsimp(((Symbol(\"x\"))^(Symbol(\"C1\")))^(Symbol(\"y\")), list(Symbol(\"C1\")))"), "(x^C1)^y")
  expect_equal(.odetest("constantsimp((Integer(2))^(Symbol(\"C1\")), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp(exp(Symbol(\"C1\")), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp(exp((Symbol(\"C1\") + Symbol(\"x\"))), list(Symbol(\"C1\")))"), "C1*exp(x)")
})

test_that("ode test_constant_function", {
  expect_equal(.odetest("constantsimp(sin(Symbol(\"C1\")), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C1\")), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C1\"), Symbol(\"C1\")), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C1\"), Symbol(\"C2\")), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C2\"), Symbol(\"C1\")), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C2\"), Symbol(\"C2\")), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C2")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C1\"), Symbol(\"x\")), list(Symbol(\"C1\")))"), "f(C1, x)")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C1\"), Symbol(\"y\")), list(Symbol(\"C1\"), Symbol(\"y\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"y\"), Symbol(\"C1\")), list(Symbol(\"C1\"), Symbol(\"y\")))"), "C1")
  expect_equal(.odetest("constantsimp(Function(\"f\")(Symbol(\"C1\"), Symbol(\"y\"), Symbol(\"C2\")), list(Symbol(\"C1\"), Symbol(\"C2\"), Symbol(\"y\")))"), "C1")
})

