  expect_equal(.odetest("constantsimp((Integer(2) + (Integer(2)*Symbol(\"C1\"))), list(Symbol(\"C1\")))"), "C1")
  expect_equal(.odetest("constantsimp((Integer(2)*Symbol(\"x\")*(Symbol(\"C1\"))^(Integer(-1))), list(Symbol(\"C1\")))"), "C1*x")
