test_that("ode test_ode_solutions", {
  expect_equal(.odetest("constant_renumber(((Symbol(\"C1\")*exp(Symbol(\"x\"))) + (Symbol(\"C2\")*exp((Integer(2)*Symbol(\"x\"))))))"), "C1*exp(x) + C2*exp(2*x)")
  expect_equal(.odetest("constantsimp(((Symbol(\"C1\")*exp((Integer(2)*Symbol(\"x\")))) + ((Symbol(\"C2\") + Symbol(\"C3\"))*exp(Symbol(\"x\")))), list(Symbol(\"C1\"), Symbol(\"C2\"), Symbol(\"C3\")))"), "C1*exp(2*x) + C2*exp(x)")
  expect_equal(.odetest("constant_renumber(Eq(Function(\"f\")(Symbol(\"x\")), ((Symbol(\"C1\")*sinh((Rational(1, 3)*Symbol(\"x\")))) + (Symbol(\"C2\")*cosh((Rational(1, 3)*Symbol(\"x\")))))))"), "Eq(f(x), C1*sinh(x/3) + C2*cosh(x/3))")
  expect_equal(.odetest("constantsimp(Eq(Function(\"f\")(Symbol(\"x\")), ((Symbol(\"C2\")*cosh((Rational(1, 3)*Symbol(\"x\")))) + (sym_I*Symbol(\"C1\")*sinh((Rational(1, 3)*Symbol(\"x\")))))), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "Eq(f(x), C1*sinh(x/3) + C2*cosh(x/3))")
  expect_equal(.odetest("constantsimp(Eq(Function(\"f\")(Symbol(\"x\")), acos((Integer(-1)*Symbol(\"C1\")*(cos(Symbol(\"x\")))^(Integer(-1))))), list(Symbol(\"C1\")))"), "Eq(f(x), acos(C1/cos(x)))")
  expect_equal(.odetest("constantsimp(Eq(((Integer(2)*exp((Symbol(\"x\")*(Function(\"f\")(Symbol(\"x\")))^(Integer(-1))))) + log(((Symbol(\"C1\"))^(Integer(-1))*Function(\"f\")(Symbol(\"x\"))))), Integer(0)), list(Symbol(\"C1\")))"), "Eq(2*exp(x/f(x)) + log(C1*f(x)), 0)")
  expect_equal(.odetest("constantsimp(Eq(((Rational(-1, 2)*cos(((Symbol(\"x\"))^(Integer(-1))*Function(\"f\")(Symbol(\"x\"))))*exp((Integer(-1)*(Symbol(\"x\"))^(Integer(-1))*Function(\"f\")(Symbol(\"x\"))))) + (Rational(-1, 2)*exp((Integer(-1)*(Symbol(\"x\"))^(Integer(-1))*Function(\"f\")(Symbol(\"x\"))))*sin(((Symbol(\"x\"))^(Integer(-1))*Function(\"f\")(Symbol(\"x\"))))) + log((Symbol(\"x\")*(Symbol(\"C1\"))^(Integer(-1))))), Integer(0)), list(Symbol(\"C1\")))"), "Eq(log(C1*x) - exp(-f(x)/x)*sin(f(x)/x)/2 - exp(-f(x)/x)*cos(f(x)/x)/2, 0)")
  expect_equal(.odetest("constantsimp(Eq(((Integer(-1)*Integral((Integer(-1)*(Symbol(\"u2\"))^(Integer(-1))*((Integer(1) + (Integer(-1)*(Symbol(\"u2\"))^(Integer(2)))))^(Rational(-1, 2))), list(Symbol(\"u2\"), Symbol(\"_a\"), (Symbol(\"x\")*(Function(\"f\")(Symbol(\"x\")))^(Integer(-1)))))) + log(((Symbol(\"C1\"))^(Integer(-1))*Function(\"f\")(Symbol(\"x\"))))), Integer(0)), list(Symbol(\"C1\")))"), "Eq(log(C1*f(x)) - Integral(-1/(u2*sqrt(1 - u2^2)), (u2, _a, x/f(x))), 0)")
})

