test_that("ode test_classify_ode", {
  expect_equal(.odetest("classify_ode(Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), list(Symbol(\"x\", real = TRUE), 2)), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('nth_algebraic', 'nth_linear_constant_coeff_homogeneous', 'nth_linear_euler_eq_homogeneous', 'Liouville', '2nd_power_series_ordinary', 'nth_algebraic_Integral', 'Liouville_Integral')")
  expect_equal(.odetest("classify_ode(Function(\"f\")(Symbol(\"x\", real = TRUE)), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('nth_algebraic', 'nth_algebraic_Integral')")
  expect_equal(.odetest("classify_ode(Eq(Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), Symbol(\"x\", real = TRUE)), Integer(0)), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('nth_algebraic', 'separable', '1st_exact', '1st_linear', 'Bernoulli', '1st_homogeneous_coeff_best', '1st_homogeneous_coeff_subs_indep_div_dep', '1st_homogeneous_coeff_subs_dep_div_indep', '1st_power_series', 'lie_group', 'nth_linear_constant_coeff_homogeneous', 'nth_linear_euler_eq_homogeneous', 'nth_algebraic_Integral', 'separable_Integral', '1st_exact_Integral', '1st_linear_Integral', 'Bernoulli_Integral', '1st_homogeneous_coeff_subs_indep_div_dep_Integral', '1st_homogeneous_coeff_subs_dep_div_indep_Integral')")
  expect_equal(.odetest("classify_ode((Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), Symbol(\"x\", real = TRUE)))^(Integer(2)), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('factorable', 'nth_algebraic', 'separable', '1st_exact', '1st_linear', 'Bernoulli', '1st_homogeneous_coeff_best', '1st_homogeneous_coeff_subs_indep_div_dep', '1st_homogeneous_coeff_subs_dep_div_indep', '1st_power_series', 'lie_group', 'nth_linear_euler_eq_homogeneous', 'nth_algebraic_Integral', 'separable_Integral', '1st_exact_Integral', '1st_linear_Integral', 'Bernoulli_Integral', '1st_homogeneous_coeff_subs_indep_div_dep_Integral', '1st_homogeneous_coeff_subs_dep_div_indep_Integral')")
  expect_equal(.odetest("classify_ode(Eq((Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), Symbol(\"x\", real = TRUE)) + Function(\"f\")(Symbol(\"x\", real = TRUE))), Symbol(\"x\", real = TRUE)), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('1st_exact', '1st_linear', 'Bernoulli', 'almost_linear', '1st_power_series', 'lie_group', 'nth_linear_constant_coeff_undetermined_coefficients', 'nth_linear_constant_coeff_variation_of_parameters', '1st_exact_Integral', '1st_linear_Integral', 'Bernoulli_Integral', 'almost_linear_Integral', 'nth_linear_constant_coeff_variation_of_parameters_Integral')")
  expect_equal(.odetest("classify_ode(((Function(\"f\")(Symbol(\"x\", real = TRUE)))^(Integer(2)) + (Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), Symbol(\"x\", real = TRUE))*Function(\"f\")(Symbol(\"x\", real = TRUE))) + (Integer(-1)*Symbol(\"x\", real = TRUE)*Function(\"f\")(Symbol(\"x\", real = TRUE)))), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('factorable', '1st_linear', 'Bernoulli', '1st_power_series', 'lie_group', 'nth_linear_constant_coeff_undetermined_coefficients', 'nth_linear_constant_coeff_variation_of_parameters', '1st_linear_Integral', 'Bernoulli_Integral', 'nth_linear_constant_coeff_variation_of_parameters_Integral')")
  expect_equal(.odetest("classify_ode((Integer(1) + ((Function(\"f\")(Symbol(\"x\", real = TRUE)))^(Integer(-1))*Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), Symbol(\"x\", real = TRUE))) + (Integer(-1)*Symbol(\"x\", real = TRUE)*(Function(\"f\")(Symbol(\"x\", real = TRUE)))^(Integer(-1)))), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('factorable', '1st_linear', 'Bernoulli', '1st_power_series', 'lie_group', 'nth_linear_constant_coeff_undetermined_coefficients', 'nth_linear_constant_coeff_variation_of_parameters', '1st_linear_Integral', 'Bernoulli_Integral', 'nth_linear_constant_coeff_variation_of_parameters_Integral')")
  expect_equal(.odetest("classify_ode(((Integer(-1)*exp(Symbol(\"x\", real = TRUE))) + ((Function(\"f\")(Symbol(\"x\", real = TRUE)))^(Integer(2))*(Integer(1) + Symbol(\"x\", real = TRUE))) + (Integer(2)*Symbol(\"x\", real = TRUE)*Derivative(Function(\"f\")(Symbol(\"x\", real = TRUE)), Symbol(\"x\", real = TRUE))*Function(\"f\")(Symbol(\"x\", real = TRUE)))), Function(\"f\")(Symbol(\"x\", real = TRUE)))"), "('1st_exact', 'Bernoulli', 'almost_linear', 'lie_group', '1st_exact_Integral', 'Bernoulli_Integral', 'almost_linear_Integral')")
