test_that("ode test_classify_sysode", {
  expect_equal(.odetest("classify_sysode(list(Eq(Derivative(Function(\"x\")(Symbol(\"t\")), Symbol(\"t\")), (Function(\"P\")(Function(\"x\")(Symbol(\"t\")), Function(\"y\")(Symbol(\"t\")))*exp((Symbol(\"k\", Integer = TRUE)*Function(\"x\")(Symbol(\"t\")))))), Eq(Derivative(Function(\"y\")(Symbol(\"t\")), Symbol(\"t\")), (Function(\"P\")(Function(\"x\")(Symbol(\"t\")), Function(\"y\")(Symbol(\"t\")))*Function(\"r\")(Function(\"y\")(Symbol(\"t\")))))))"), "{'eq': [-P(x(t), y(t))*exp(k*x(t)) + Derivative(x(t), t), -P(x(t), y(t))*r(y(t)) + Derivative(y(t), t)], 'func': [x(t), y(t)], 'func_coeff': {(0, x(t), 0): 0, (0, x(t), 1): 1, (0, y(t), 0): 0, (0, y(t), 1): 0, (1, x(t), 0): 0, (1, x(t), 1): 0, (1, y(t), 0): 0, (1, y(t), 1): 1}, 'is_linear': False, 'no_of_equation': 2, 'order': {x(t): 1, y(t): 1}, 'type_of_equation': 'type2'}")
  expect_equal(.odetest("classify_sysode(list(Eq(Derivative(Function(\"x\")(Symbol(\"t\")), Symbol(\"t\")), ((Function(\"x\")(Symbol(\"t\")))^(Integer(2)) + ((Function(\"x\")(Symbol(\"t\")))^(Integer(-1))*Function(\"y\")(Symbol(\"t\"))))), Eq(Derivative(Function(\"y\")(Symbol(\"t\")), Symbol(\"t\")), ((Function(\"y\")(Symbol(\"t\")))^(Integer(-1))*Function(\"x\")(Symbol(\"t\"))))))"), "{'eq': [-x(t)^2 + Derivative(x(t), t) - y(t)/x(t), -x(t)/y(t) + Derivative(y(t), t)], 'func': [x(t), y(t)], 'func_coeff': {(0, x(t), 0): 0, (0, x(t), 1): 1, (0, y(t), 0): -1/x(t), (0, y(t), 1): 0, (1, x(t), 0): -1/y(t), (1, x(t), 1): 0, (1, y(t), 0): 0, (1, y(t), 1): 1}, 'is_linear': False, 'no_of_equation': 2, 'order': {x(t): 1, y(t): 1}, 'type_of_equation': 'type3'}")
  expect_equal(.odetest("classify_sysode(list(Eq(Derivative(Function(\"x\")(Symbol(\"t\")), Symbol(\"t\")), (Function(\"P1\")(Function(\"x\")(Symbol(\"t\")))*Function(\"Q1\")(Function(\"y\")(Symbol(\"t\")))*Function(\"R\")(Function(\"x\")(Symbol(\"t\")), Function(\"y\")(Symbol(\"t\")), Symbol(\"t\")))), Eq(Derivative(Function(\"y\")(Symbol(\"t\")), Symbol(\"t\")), (Function(\"P1\")(Function(\"x\")(Symbol(\"t\")))*Function(\"Q1\")(Function(\"y\")(Symbol(\"t\")))*Function(\"R\")(Function(\"x\")(Symbol(\"t\")), Function(\"y\")(Symbol(\"t\")), Symbol(\"t\"))))))"), "{'eq': [-P1(x(t))*Q1(y(t))*R(x(t), y(t), t) + Derivative(x(t), t), -P1(x(t))*Q1(y(t))*R(x(t), y(t), t) + Derivative(y(t), t)], 'func': [x(t), y(t)], 'func_coeff': {(0, x(t), 0): 0, (0, x(t), 1): 1, (0, y(t), 0): 0, (0, y(t), 1): 0, (1, x(t), 0): 0, (1, x(t), 1): 0, (1, y(t), 0): 0, (1, y(t), 1): 1}, 'is_linear': False, 'no_of_equation': 2, 'order': {x(t): 1, y(t): 1}, 'type_of_equation': 'type4'}")
  expect_equal(.odetest("classify_sysode(list(Eq(Derivative(Function(\"x\")(Symbol(\"t\")), Symbol(\"t\")), ((Function(\"y\")(Symbol(\"t\")))^(Integer(3))*Function(\"x\")(Symbol(\"t\")))), Eq(Derivative(Function(\"y\")(Symbol(\"t\")), Symbol(\"t\")), (Function(\"y\")(Symbol(\"t\")))^(Integer(5)))))"), "{'eq': [-x(t)*y(t)^3 + Derivative(x(t), t), -y(t)^5 + Derivative(y(t), t)], 'func': [x(t), y(t)], 'func_coeff': {(0, x(t), 0): -y(t)^3, (0, x(t), 1): 1, (0, y(t), 0): 0, (0, y(t), 1): 0, (1, x(t), 0): 0, (1, x(t), 1): 0, (1, y(t), 0): 0, (1, y(t), 1): 1}, 'is_linear': False, 'no_of_equation': 2, 'order': {x(t): 1, y(t): 1}, 'type_of_equation': 'type1'}")
  expect_equal(.odetest("classify_sysode(list(Eq(Derivative(Function(\"x\")(Symbol(\"t\")), Symbol(\"t\")), ((sin(Symbol(\"t\")))^(Integer(2))*Function(\"x\")(Symbol(\"t\"))*Function(\"y\")(Symbol(\"t\")))), Eq(Derivative(Function(\"y\")(Symbol(\"t\")), Symbol(\"t\")), ((sin(Symbol(\"t\")))^(Integer(2))*(Function(\"y\")(Symbol(\"t\")))^(Integer(2))))))"), "{'eq': [-x(t)*y(t)*sin(t)^2 + Derivative(x(t), t), -y(t)^2*sin(t)^2 + Derivative(y(t), t)], 'func': [x(t), y(t)], 'func_coeff': {(0, x(t), 0): -y(t)*sin(t)^2, (0, x(t), 1): 1, (0, y(t), 0): -x(t)*sin(t)^2, (0, y(t), 1): 0, (1, x(t), 0): 0, (1, x(t), 1): 0, (1, y(t), 0): 0, (1, y(t), 1): 1}, 'is_linear': False, 'no_of_equation': 2, 'order': {x(t): 1, y(t): 1}, 'type_of_equation': 'type4'}")
