test_that("ode test_issue_5770", {
  expect_equal(.odetest("dsolve(((Integer(-1)*(Symbol(\"k\", real = TRUE))^(Integer(6))*Function(\"w\")(Symbol(\"t\"))) + Derivative(Function(\"w\")(Symbol(\"t\")), list(Symbol(\"t\"), 6))), Function(\"w\")(Symbol(\"t\")))"), "Eq(w(t), C5*exp(-k*t) + C6*exp(k*t) + (C1*sin(sqrt(3)*t*Abs(k)/2) + C2*cos(sqrt(3)*k*t/2))*exp(-k*t/2) + (C3*sin(sqrt(3)*t*Abs(k)/2) + C4*cos(sqrt(3)*k*t/2))*exp(k*t/2))")
  expect_equal(.odetest("constantsimp((((Symbol(\"C1\")*cos(Symbol(\"x\", real = TRUE))) + (Symbol(\"C2\")*cos(Symbol(\"x\", real = TRUE))))*exp(Symbol(\"x\", real = TRUE))), list(Symbol(\"C1\"), Symbol(\"C2\")))"), "C1*exp(x)*cos(x)")
  expect_equal(.odetest("constantsimp(((Symbol(\"C1\")*cos(Symbol(\"x\", real = TRUE))) + (Symbol(\"C2\")*cos(Symbol(\"x\", real = TRUE))) + (Symbol(\"C3\")*sin(Symbol(\"x\", real = TRUE)))), list(Symbol(\"C1\"), Symbol(\"C2\"), Symbol(\"C3\")))"), "C1*cos(x) + C3*sin(x)")
