test_that("odesys test_canonical_odes", {
  expect_equal(.odetest("canonical_odes(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)), ((Integer(2)*Function(\"g\")(Symbol(\"x\"))) + Function(\"f\")(Symbol(\"x\")))), Eq((Integer(1) + Function(\"g\")(Symbol(\"x\"))), (Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")) + Function(\"f\")(Symbol(\"x\"))))), list(Function(\"f\")(Symbol(\"x\")), Function(\"g\")(Symbol(\"x\"))), Symbol(\"x\"))"), "[[Eq(Derivative(f(x), (x, 2)), f(x) + 2*g(x)), Eq(Derivative(g(x), x), -f(x) + g(x) + 1)]]")
  expect_equal(.odetest("canonical_odes(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), (Derivative(Function(\"h\")(Symbol(\"x\")), Symbol(\"x\")) + Function(\"f\")(Symbol(\"x\")))), Eq((Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")))^(Integer(2)), (Function(\"f\")(Symbol(\"x\")) + Function(\"h\")(Symbol(\"x\")))), Eq(Derivative(Function(\"h\")(Symbol(\"x\")), Symbol(\"x\")), Function(\"f\")(Symbol(\"x\")))), list(Function(\"f\")(Symbol(\"x\")), Function(\"g\")(Symbol(\"x\")), Function(\"h\")(Symbol(\"x\"))), Symbol(\"x\"))"), "[[Eq(Derivative(f(x), x), 2*f(x)), Eq(Derivative(g(x), x), -sqrt(f(x) + h(x))), Eq(Derivative(h(x), x), f(x))], [Eq(Derivative(f(x), x), 2*f(x)), Eq(Derivative(g(x), x), sqrt(f(x) + h(x))), Eq(Derivative(h(x), x), f(x))]]")
})

