  expect_equal(.odetest("checksysodesol(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(-1))*((Integer(2)*Function(\"f\")(Symbol(\"x\"))) + Function(\"g\")(Symbol(\"x\"))))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(-1))*((Integer(2)*Function(\"g\")(Symbol(\"x\"))) + Function(\"f\")(Symbol(\"x\")))))), list(Eq(Function(\"f\")(Symbol(\"x\")), ((Symbol(\"C2\")*(Symbol(\"x\"))^(Integer(3))) + (Integer(-1)*Symbol(\"C1\")*Symbol(\"x\")))), Eq(Function(\"g\")(Symbol(\"x\")), ((Symbol(\"C1\")*Symbol(\"x\")) + (Symbol(\"C2\")*(Symbol(\"x\"))^(Integer(3)))))))"), "(True, [0, 0])")
  expect_equal(.odetest("dsolve(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(-1))*(Integer(1) + (Integer(2)*Function(\"f\")(Symbol(\"x\"))) + Function(\"g\")(Symbol(\"x\"))))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(-1))*(Symbol(\"x\") + (Integer(2)*Function(\"g\")(Symbol(\"x\"))) + Function(\"f\")(Symbol(\"x\")))))))"), "[Eq(f(x), C2*x^3 - x*(C1 + 1/4) - x*log(x)/2 - 2/3), Eq(g(x), C2*x^3 + x*(C1 - 1/4) + x*log(x)/2 + 1/3)]")
  expect_equal(.odetest("checksysodesol(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(-1))*(Integer(1) + (Integer(2)*Function(\"f\")(Symbol(\"x\"))) + Function(\"g\")(Symbol(\"x\"))))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(-1))*(Symbol(\"x\") + (Integer(2)*Function(\"g\")(Symbol(\"x\"))) + Function(\"f\")(Symbol(\"x\")))))), list(Eq(Function(\"f\")(Symbol(\"x\")), (Rational(-2, 3) + (Symbol(\"C2\")*(Symbol(\"x\"))^(Integer(3))) + (Integer(-1)*Symbol(\"x\")*(Rational(1, 4) + Symbol(\"C1\"))) + (Rational(-1, 2)*Symbol(\"x\")*log(Symbol(\"x\"))))), Eq(Function(\"g\")(Symbol(\"x\")), (Rational(1, 3) + (Symbol(\"C2\")*(Symbol(\"x\"))^(Integer(3))) + (Symbol(\"x\")*(Rational(-1, 4) + Symbol(\"C1\"))) + (Rational(1, 2)*Symbol(\"x\")*log(Symbol(\"x\")))))))"), "(True, [0, 0])")
})

test_that("odesys test_higher_order_to_first_order_12", {
