(1, 2))*(Integer(2) + (Integer(-1)*(Integer(5))^(Rational(1, 2))))*sin((Integer(2)*Symbol(\"t\")*((Integer(9) + (Integer(4)*(Integer(5))^(Rational(1, 2)))))^(Rational(1, 2)))))))))"), "(True, [0, 0])")
})

test_that("odesys test_second_order_to_first_order_2", {
  expect_equal(.odetest("dsolve(list(Eq(Derivative(Function(\"g\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), (Symbol(\"a\")*Symbol(\"m\"))), Eq(Derivative(Function(\"f\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), Integer(0))))"), "[Eq(g(t), C1 + C2*t + a*m*t^2/2), Eq(f(t), C3 + C4*t)]")
  expect_equal(.odetest("checksysodesol(list(Eq(Derivative(Function(\"g\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), (Symbol(\"a\")*Symbol(\"m\"))), Eq(Derivative(Function(\"f\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), Integer(0))), list(Eq(Function(\"g\")(Symbol(\"t\")), (Symbol(\"C1\") + (Symbol(\"C2\")*Symbol(\"t\")) + (Rational(1, 2)*Symbol(\"a\")*Symbol(\"m\")*(Symbol(\"t\"))^(Integer(2))))), Eq(Function(\"f\")(Symbol(\"t\")), (Symbol(\"C3\") + (Symbol(\"C4\")*Symbol(\"t\"))))))"), "(True, [0, 0])")
  expect_equal(.odetest("dsolve(list(Eq(Derivative(Function(\"f\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), ((Symbol(\"t\"))^(Integer(-4))*Function(\"f\")(Symbol(\"t\")))), Eq(Derivative(Function(\"g\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), (Symbol(\"d\")*(Symbol(\"t\"))^(Integer(-4))*Function(\"g\")(Symbol(\"t\"))))))"), "[Eq(f(t), C1*sqrt(t^2)*exp(-1/t) - C2*sqrt(t^2)*exp(1/t)), Eq(g(t), C3*sqrt(t^2)*exp(-sqrt(d)/t)/sqrt(d) - C4*sqrt(t^2)*exp(sqrt(d)/t)/sqrt(d))]")
  expect_equal(.odetest("checksysodesol(list(Eq(Derivative(Function(\"f\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), ((Symbol(\"t\"))^(Integer(-4))*Function(\"f\")(Symbol(\"t\")))), Eq(Derivative(Function(\"g\")(Symbol(\"t\")), list(Symbol(\"t\"), 2)), (Symbol(\"d\")*(Symbol(\"t\"))^(Integer(-4))*Function(\"g\")(Symbol(\"t\"))))), list(Eq(Function(\"f\")(Symbol(\"t\")), ((Symbol(\"C1\")*((Symbol(\"t\"))^(Integer(2)))^(Rational(1, 2))*exp((Integer(-1)*(Symbol(\"t\"))^(Integer(-1))))) + (Integer(-1)*Symbol(\"C2\")*((Symbol(\"t\"))^(Integer(2)))^(Rational(1, 2))*exp((Symbol(\"t\"))^(Integer(-1)))))), Eq(Function(\"g\")(Symbol(\"t\")), ((Symbol(\"C3\")*(Symbol(\"d\"))^(Rational(-1, 2))*((Symbol(\"t\"))^(Integer(2)))^(Rational(1, 2))*exp((Integer(-1)*(Symbol(\"d\"))^(Rational(1, 2))*(Symbol(\"t\"))^(Integer(-1))))) + (Integer(-1)*Symbol(\"C4\")*(Symbol(\"d\"))^(Rational(-1, 2))*((Symbol(\"t\"))^(Integer(2)))^(Rational(1, 2))*exp(((Symbol(\"d\"))^(Rational(1, 2))*(Symbol(\"t\"))^(Integer(-1)))))))))"), "(True, [0, 0])")
})

test_that("odesys test_linodesolve", {
  expect_equal(.odetest("linodesolve(Integer(1), Symbol(\"t\"))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve(Symbol(\"a\"), Symbol(\"t\"))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(2)), list(Integer(2), Integer(4)), list(Integer(4), Integer(6)))), Symbol(\"t\"))"), "ERR NonSquareMatrixError: \\nThe coefficient matrix must be a square")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(2), Integer(1)), list(Integer(3), Integer(1), Integer(2)))), Symbol(\"t\"))"), "ERR NonSquareMatrixError: \\nThe coefficient matrix must be a square")
  expect_equal(.odetest("canonical_odes(list(Eq((Derivative(Function(\"f\")(Symbol(\"t\")), Symbol(\"t\")) + Derivative(Function(\"g\")(Symbol(\"t\")), Symbol(\"t\"))), Function(\"g\")(Symbol(\"t\"))), Eq(Derivative(Function(\"g\")(Symbol(\"t\")), Symbol(\"t\")), Function(\"f\")(Symbol(\"t\")))), list(Function(\"f\")(Symbol(\"t\")), Function(\"g\")(Symbol(\"t\"))), Symbol(\"t\"))"), "[[Eq(Derivative(f(t), t), -f(t) + g(t)), Eq(Derivative(g(t), t), f(t))]]")
  expect_equal(.odetest("linear_ode_to_matrix(list(Eq(Derivative(Function(\"f\")(Symbol(\"t\")), Symbol(\"t\")), ((Integer(-1)*Function(\"f\")(Symbol(\"t\"))) + Function(\"g\")(Symbol(\"t\")))), Eq(Derivative(Function(\"g\")(Symbol(\"t\")), Symbol(\"t\")), Function(\"f\")(Symbol(\"t\")))), list(Function(\"f\")(Symbol(\"t\")), Function(\"g\")(Symbol(\"t\"))), Symbol(\"t\"), Integer(1))"), "([Matrix([\\n[1, 0],\\n[0, 1]]), Matrix([\\n[-1, 1],\\n[ 1, 0]])], Matrix([\\n[0],\\n[0]]))")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(-1), Integer(1)), list(Integer(1), Integer(0)))), Symbol(\"t\"))"), "[_Dummy_0*exp(t*(-1/2 + sqrt(5)/2)) + _Dummy_1*exp(t*(-sqrt(5)/2 - 1/2)), _Dummy_0*(1/2 + sqrt(5)/2)*exp(t*(-1/2 + sqrt(5)/2)) + _Dummy_1*(1/2 - sqrt(5)/2)*exp(t*(-sqrt(5)/2 - 1/2))]")
  expect_equal(.odetest("linodesolve(Integer(1), Symbol(\"t\"), b = Matrix(list(list((Integer(1) + Symbol(\"t\"))))))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve(Symbol(\"a\"), Symbol(\"t\"), b = Matrix(list(list((log(Symbol(\"t\")) + sin(Symbol(\"t\")))))))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(7)))), Symbol(\"t\"), b = (Symbol(\"t\"))^(Integer(2)))"), "ERR ValueError: \\nThe non-homogeneous terms of the system of ODEs should be of type\\nMatrix")
  expect_equal(.odetest("linodesolve(Matrix(list(list((Integer(10) + Symbol(\"a\"))))), Symbol(\"t\"), b = (cos(Symbol(\"t\"))*log(Symbol(\"t\"))))"), "ERR ValueError: \\nThe non-homogeneous terms of the system of ODEs should be of type\\nMatrix")
  expect_equal(.odetest("linodesolve(Integer(7), Symbol(\"t\"), b = (Symbol(\"t\"))^(Integer(2)))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve(Symbol(\"a\"), Symbol(\"t\"), b = (log(Symbol(\"t\")) + sin(Symbol(\"t\"))))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(2)), list(Integer(2), Integer(4)), list(Integer(4), Integer(6)))), Symbol(\"t\"), b = Matrix(list(list(Symbol(\"t\")), list(Integer(1)), list((Symbol(\"t\"))^(Integer(2))))))"), "ERR NonSquareMatrixError: \\nThe coefficient matrix must be a square")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(2), Integer(1)), list(Integer(3), Integer(1), Integer(2)))), Symbol(\"t\"), b = Matrix(list(list(Symbol(\"t\")), list((Symbol(\"t\"))^(Integer(2))))))"), "ERR NonSquareMatrixError: \\nThe coefficient matrix must be a square")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(2)), list(Integer(2), Integer(4)))), Symbol(\"t\"), b = Matrix(list(list(Symbol(\"t\")), list(Integer(1)), list((Symbol(\"t\"))^(Integer(2))))))"), "ERR ValueError: \\nThe system of ODEs should have the same number of non-homogeneous\\nterms and the number of equations")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(2)), list(Integer(2), Integer(4)))), Symbol(\"t\"), b = list(Symbol(\"t\")))"), "ERR ValueError: \\nThe non-homogeneous terms of the system of ODEs should be of type\\nMatrix")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Integer(-1)), list(Integer(1), Integer(-1)))), Symbol(\"t\"), b = Matrix(list(list((Integer(-10) + (Integer(15)*Symbol(\"t\")))), list((Integer(-5) + (Integer(-15)*Symbol(\"t\")))))), type = \"type2\", doit = TRUE)"), "[_Dummy_0 + _Dummy_1*t + _Dummy_1 - 10*t^3 + 10*t^2 + t*(15*t^2 - 5*t) - 10*t, _Dummy_0 + _Dummy_1*t - 10*t^3 - 5*t^2 + t*(15*t^2 - 5*t) - 5*t]")
  expect_equal(.odetest("canonical_odes(list(Eq((Derivative(Function(\"f\")(Symbol(\"t\")), Symbol(\"t\")) + Derivative(Function(\"g\")(Symbol(\"t\")), Symbol(\"t\"))), (Symbol(\"t\") + Function(\"g\")(Symbol(\"t\")))), Eq(Derivative(Function(\"g\")(Symbol(\"t\")), Symbol(\"t\")), Function(\"f\")(Symbol(\"t\")))), list(Function(\"f\")(Symbol(\"t\")), Function(\"g\")(Symbol(\"t\"))), Symbol(\"t\"))"), "[[Eq(Derivative(f(t), t), t - f(t) + g(t)), Eq(Derivative(g(t), t), f(t))]]")
  expect_equal(.odetest("linear_ode_to_matrix(list(Eq(Derivative(Function(\"f\")(Symbol(\"t\")), Symbol(\"t\")), (Symbol(\"t\") + (Integer(-1)*Function(\"f\")(Symbol(\"t\"))) + Function(\"g\")(Symbol(\"t\")))), Eq(Derivative(Function(\"g\")(Symbol(\"t\")), Symbol(\"t\")), Function(\"f\")(Symbol(\"t\")))), list(Function(\"f\")(Symbol(\"t\")), Function(\"g\")(Symbol(\"t\"))), Symbol(\"t\"), Integer(1))"), "([Matrix([\\n[1, 0],\\n[0, 1]]), Matrix([\\n[-1, 1],\\n[ 1, 0]])], Matrix([\\n[t],\\n[0]]))")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(-1), Integer(1)), list(Integer(1), Integer(0)))), Symbol(\"t\"), b = Matrix(list(list(Symbol(\"t\")), list(Integer(0)))))"), "[_Dummy_0*exp(-t/2 + sqrt(5)*t/2) + _Dummy_1*exp(-sqrt(5)*t/2 - t/2) + exp(-t/2 + sqrt(5)*t/2)*Integral(-sqrt(5)*t*exp(-sqrt(5)*t/2 + t/2)/10 + t*exp(-sqrt(5)*t/2 + t/2)/2, t) + exp(-sqrt(5)*t/2 - t/2)*Integral(sqrt(5)*t*exp(t/2 + sqrt(5)*t/2)/10 + t*exp(t/2 + sqrt(5)*t/2)/2, t), _Dummy_0*exp(-t/2 + sqrt(5)*t/2)/2 + sqrt(5)*_Dummy_0*exp(-t/2 + sqrt(5)*t/2)/2 - sqrt(5)*_Dummy_1*exp(-sqrt(5)*t/2 - t/2)/2 + _Dummy_1*exp(-sqrt(5)*t/2 - t/2)/2 + exp(-t/2 + sqrt(5)*t/2)*Integral(-sqrt(5)*t*exp(-sqrt(5)*t/2 + t/2)/10 + t*exp(-sqrt(5)*t/2 + t/2)/2, t)/2 + sqrt(5)*exp(-t/2 + sqrt(5)*t/2)*Integral(-sqrt(5)*t*exp(-sqrt(5)*t/2 + t/2)/10 + t*exp(-sqrt(5)*t/2 + t/2)/2, t)/2 - sqrt(5)*exp(-sqrt(5)*t/2 - t/2)*Integral(sqrt(5)*t*exp(t/2 + sqrt(5)*t/2)/10 + t*exp(t/2 + sqrt(5)*t/2)/2, t)/2 + exp(-sqrt(5)*t/2 - t/2)*Integral(sqrt(5)*t*exp(t/2 + sqrt(5)*t/2)/10 + t*exp(t/2 + sqrt(5)*t/2)/2, t)/2]")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(-1), Integer(1)), list(Integer(1), Integer(0)))), Symbol(\"t\"), type = \"type2\")"), "[_Dummy_0*exp(-t/2 + sqrt(5)*t/2) + _Dummy_1*exp(-sqrt(5)*t/2 - t/2), _Dummy_0*exp(-t/2 + sqrt(5)*t/2)/2 + sqrt(5)*_Dummy_0*exp(-t/2 + sqrt(5)*t/2)/2 - sqrt(5)*_Dummy_1*exp(-sqrt(5)*t/2 - t/2)/2 + _Dummy_1*exp(-sqrt(5)*t/2 - t/2)/2]")
  expect_equal(.odetest("linodesolve((Integer(10) + Symbol(\"t\")), Symbol(\"t\"))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("linodesolve((Symbol(\"a\")*Symbol(\"t\")), Symbol(\"t\"))"), "ERR ValueError: \\nThe coefficients of the system of ODEs should be of type Matrix")
  expect_equal(.odetest("symcompR:::.ode_is_commutative_anti_derivative(Matrix(list(list(Integer(1), Symbol(\"t\")), list((Integer(-1)*Symbol(\"t\")), Integer(1)))), Symbol(\"t\"))"), "(Matrix([\\n[      t, t^2/2],\\n[-t^2/2,      t]]), True)")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1)), list((Integer(-1)*Symbol(\"t\"))))), Symbol(\"t\"), B = Matrix(list(list(Symbol(\"t\"), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))), list((Rational(-1, 2)*(Symbol(\"t\"))^(Integer(2))), Symbol(\"t\")))))"), "ERR NonSquareMatrixError: \\nThe coefficient matrix must be a square")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Symbol(\"t\")), list((Integer(-1)*Symbol(\"t\")), Integer(1)))), Symbol(\"t\"), B = 1)"), "ERR ValueError: \\nThe antiderivative of coefficients of the system of ODEs should be of\\ntype Matrix")
  expect_equal(.odetest("symcompR:::.ode_is_commutative_anti_derivative(Matrix(list(list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")))), Symbol(\"t\"))"), "(Matrix([\\n[t^2/2, t^2/2, t^2/2],\\n[t^2/2, t^2/2, t^2/2],\\n[t^2/2, t^2/2, t^2/2]]), True)")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")))), Symbol(\"t\"), B = Matrix(list(list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))), list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))))))"), "ERR NonSquareMatrixError: \\nThe antiderivative of the coefficient matrix must be a square")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")))), Symbol(\"t\"), B = 2)"), "ERR ValueError: \\nThe antiderivative of coefficients of the system of ODEs should be of\\ntype Matrix")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")), list(Symbol(\"t\"), Symbol(\"t\"), Symbol(\"t\")))), Symbol(\"t\"), B = Matrix(list(list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))), list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))), list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))))), type = \"type31\")"), "ERR ValueError: \\nThe input type should be a valid one")
  expect_equal(.odetest("linodesolve(Matrix(list(list(Integer(1), Symbol(\"t\")), list((Integer(-1)*Symbol(\"t\")), Integer(1)))), Symbol(\"t\"), B = Matrix(list(list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))), list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))), list((Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2))), (Rational(1, 2)*(Symbol(\"t\"))^(Integer(2)))))))"), "ERR ValueError: \\nThe coefficient matrix and its antiderivative should have same\\ndimensions")
