  expect_equal(.odetest("linodesolve(Matrix(list(list(Symbol(\"x\"), Symbol(\"x\"), Symbol(\"x\")), list(Symbol(\"x\"), Symbol(\"x\"), Symbol(\"x\")), list(Symbol(\"x\"), Symbol(\"x\"), Symbol(\"x\")))), Symbol(\"x\"), b = Matrix(list(list(Symbol(\"x\")), list(Symbol(\"x\")), list(Integer(1)))))"), "[_Dummy_0*exp(3*x^2/2)/3 + 2*_Dummy_0/3 + _Dummy_1*exp(3*x^2/2)/3 - _Dummy_1/3 + _Dummy_2*exp(3*x^2/2)/3 - _Dummy_2/3 + exp(3*x^2/2)*Integral(-2*x/3 + 2*x*exp(-3*x^2/2)/3 + 2/3 + exp(-3*x^2/2)/3, x)/3 + 2*exp(3*x^2/2)*Integral(x/3 + 2*x*exp(-3*x^2/2)/3 - 1/3 + exp(-3*x^2/2)/3, x)/3 - Integral(-2*x/3 + 2*x*exp(-3*x^2/2)/3 + 2/3 + exp(-3*x^2/2)/3, x)/3 + Integral(x/3 + 2*x*exp(-3*x^2/2)/3 - 1/3 + exp(-3*x^2/2)/3, x)/3, _Dummy_0*exp(3*x^2/2)/3 - _Dummy_0/3 + _Dummy_1*exp(3*x^2/2)/3 + 2*_Dummy_1/3 + _Dummy_2*exp(3*x^2/2)/3 - _Dummy_2/3 + exp(3*x^2/2)*Integral(-2*x/3 + 2*x*exp(-3*x^2/2)/3 + 2/3 + exp(-3*x^2/2)/3, x)/3 + 2*exp(3*x^2/2)*Integral(x/3 + 2*x*exp(-3*x^2/2)/3 - 1/3 + exp(-3*x^2/2)/3, x)/3 - Integral(-2*x/3 + 2*x*exp(-3*x^2/2)/3 + 2/3 + exp(-3*x^2/2)/3, x)/3 + Integral(x/3 + 2*x*exp(-3*x^2/2)/3 - 1/3 + exp(-3*x^2/2)/3, x)/3, _Dummy_0*exp(3*x^2/2)/3 - _Dummy_0/3 + _Dummy_1*exp(3*x^2/2)/3 - _Dummy_1/3 + _Dummy_2*exp(3*x^2/2)/3 + 2*_Dummy_2/3 + exp(3*x^2/2)*Integral(-2*x/3 + 2*x*exp(-3*x^2/2)/3 + 2/3 + exp(-3*x^2/2)/3, x)/3 + 2*exp(3*x^2/2)*Integral(x/3 + 2*x*exp(-3*x^2/2)/3 - 1/3 + exp(-3*x^2/2)/3, x)/3 + 2*Integral(-2*x/3 + 2*x*exp(-3*x^2/2)/3 + 2/3 + exp(-3*x^2/2)/3, x)/3 - 2*Integral(x/3 + 2*x*exp(-3*x^2/2)/3 - 1/3 + exp(-3*x^2/2)/3, x)/3]")
