  expect_equal(.odetest("linodesolve(Matrix(list(list(Symbol(\"t\"), Integer(1)), list(Symbol(\"t\"), Integer(-1)))), Symbol(\"t\"), b = Matrix(list(list(Symbol(\"t\")), list((Symbol(\"t\"))^(Integer(2))))))"), "ERR NotImplementedError: \\nThe system does not have a commutative antiderivative, it cannot be\\nsolved by linodesolve.")
