test_that("odesys test_neq_order1_type4_slow3", {
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\")*Function(\"f\")(Symbol(\"x\"))) + Function(\"g\")(Symbol(\"x\")) + sin(Symbol(\"x\")))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), ((Symbol(\"x\"))^(Integer(2)) + (Integer(-1)*Function(\"f\")(Symbol(\"x\"))) + (Symbol(\"x\")*Function(\"g\")(Symbol(\"x\")))))), simplify = FALSE, doit = FALSE)"), "[[Eq(f(x), (C1/2 - I*C2/2 - I*Integral(x^2*exp(-x^2/2 - I*x)/2 + x^2*exp(-x^2/2 + I*x)/2 + I*exp(-x^2/2 - I*x)*sin(x)/2 - I*exp(-x^2/2 + I*x)*sin(x)/2, x)/2 + Integral(-I*x^2*exp(-x^2/2 - I*x)/2 + I*x^2*exp(-x^2/2 + I*x)/2 + exp(-x^2/2 - I*x)*sin(x)/2 + exp(-x^2/2 + I*x)*sin(x)/2, x)/2)*exp(x^2/2 + I*x) + (C1/2 + I*C2/2 + I*Integral(x^2*exp(-x^2/2 - I*x)/2 + x^2*exp(-x^2/2 + I*x)/2 + I*exp(-x^2/2 - I*x)*sin(x)/2 - I*exp(-x^2/2 + I*x)*sin(x)/2, x)/2 + Integral(-I*x^2*exp(-x^2/2 - I*x)/2 + I*x^2*exp(-x^2/2 + I*x)/2 + exp(-x^2/2 - I*x)*sin(x)/2 + exp(-x^2/2 + I*x)*sin(x)/2, x)/2)*exp(x^2/2 - I*x)), Eq(g(x), (-I*C1/2 + C2/2 + Integral(x^2*exp(-x^2/2 - I*x)/2 + x^2*exp(-x^2/2 + I*x)/2 + I*exp(-x^2/2 - I*x)*sin(x)/2 - I*exp(-x^2/2 + I*x)*sin(x)/2, x)/2 - I*Integral(-I*x^2*exp(-x^2/2 - I*x)/2 + I*x^2*exp(-x^2/2 + I*x)/2 + exp(-x^2/2 - I*x)*sin(x)/2 + exp(-x^2/2 + I*x)*sin(x)/2, x)/2)*exp(x^2/2 - I*x) + (I*C1/2 + C2/2 + Integral(x^2*exp(-x^2/2 - I*x)/2 + x^2*exp(-x^2/2 + I*x)/2 + I*exp(-x^2/2 - I*x)*sin(x)/2 - I*exp(-x^2/2 + I*x)*sin(x)/2, x)/2 + I*Integral(-I*x^2*exp(-x^2/2 - I*x)/2 + I*x^2*exp(-x^2/2 + I*x)/2 + exp(-x^2/2 - I*x)*sin(x)/2 + exp(-x^2/2 + I*x)*sin(x)/2, x)/2)*exp(x^2/2 + I*x))]]")
})

test_that("odesys test_dsolve_system", {
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\")))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\"))))), funcs = list(Function(\"f\")(Symbol(\"x\")), Function(\"g\")(Symbol(\"x\"))), t = Symbol(\"x\"), doit = TRUE)"), "[[Eq(f(x), -C1 + C2*exp(2*x)), Eq(g(x), C1 + C2*exp(2*x))]]")
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(Integer(1))"), "ERR ValueError: \\nList of equations should be passed. The input is not valid.")
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\")))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\"))))), Integer(1))"), "ERR ValueError: \\nInput to the funcs should be a list of functions.")
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\")))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\"))))), list(Function(\"f\")(Symbol(\"x\")), Function(\"g\")(Symbol(\"x\"))), Integer(1))"), "ERR ValueError: \\nThe independent variable must be of type Symbol")
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\")))), Eq(Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")), (Function(\"f\")(Symbol(\"x\")) + Function(\"g\")(Symbol(\"x\"))))), list(Function(\"f\")(Symbol(\"x\"))), Symbol(\"x\"))"), "ERR ValueError: \\nNumber of equations and number of functions do not match")
  expect_equal(.odetest("symcompR:::.ode_dsolve_system(list(Eq(Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\")), ((Integer(-6)*Function(\"g\")(Symbol(\"x\"))) + (Integer(12)*Function(\"f\")(Symbol(\"x\"))))), Eq((Derivative(Function(\"g\")(Symbol(\"x\")), Symbol(\"x\")))^(Integer(2)), ((Integer(3)*Function(\"g\")(Symbol(\"x\"))) + (Integer(11)*Function(\"f\")(Symbol(\"x\")))))))"), "ERR NotImplementedError: \\nThe system of ODEs passed cannot be solved by dsolve_system.")
