test_that("single test_single.2nd_nonlinear_autonomous_conserved", {
  expect_equal(.odetest("classify_ode((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + exp(Function(\"f\")(Symbol(\"x\"))) + log(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")))"), "('2nd_nonlinear_autonomous_conserved', '2nd_nonlinear_autonomous_conserved_Integral')")
