  expect_equal(.odetest("dsolve(((Function(\"f\")(Symbol(\"x\")))^(Integer(-1)) + (Function(\"f\")(Symbol(\"x\")))^(Rational(1, 3)) + Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2))), Function(\"f\")(Symbol(\"x\")), hint = \"2nd_nonlinear_autonomous_conserved\", simplify = FALSE)"), "[Eq(sqrt(2)*Integral(1/sqrt(-3*_u^(4/3) + 2*C1 - 4*log(_u)), (_u, f(x))), C2 + x), Eq(sqrt(2)*Integral(1/sqrt(-3*_u^(4/3) + 2*C1 - 4*log(_u)), (_u, f(x))), C2 - x)]")
  expect_equal(.odetest("classify_ode((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + sin(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")))"), "('2nd_nonlinear_autonomous_conserved', '2nd_nonlinear_autonomous_conserved_Integral')")
  expect_equal(.odetest("dsolve((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + sin(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")), hint = \"2nd_nonlinear_autonomous_conserved\", simplify = FALSE)"), "[Eq(Integral(1/sqrt(C1 + 2*cos(_u)), (_u, f(x))), C2 + x), Eq(Integral(1/sqrt(C1 + 2*cos(_u)), (_u, f(x))), C2 - x)]")
  expect_equal(.odetest("classify_ode((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + cosh(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")))"), "('2nd_nonlinear_autonomous_conserved', '2nd_nonlinear_autonomous_conserved_Integral')")
  expect_equal(.odetest("dsolve((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + cosh(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")), hint = \"2nd_nonlinear_autonomous_conserved\", simplify = FALSE)"), "[Eq(Integral(1/sqrt(C1 - 2*sinh(_u)), (_u, f(x))), C2 + x), Eq(Integral(1/sqrt(C1 - 2*sinh(_u)), (_u, f(x))), C2 - x)]")
  expect_equal(.odetest("classify_ode((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + asin(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")))"), "('2nd_nonlinear_autonomous_conserved', '2nd_nonlinear_autonomous_conserved_Integral')")
  expect_equal(.odetest("dsolve((Derivative(Function(\"f\")(Symbol(\"x\")), list(Symbol(\"x\"), 2)) + asin(Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")), hint = \"2nd_nonlinear_autonomous_conserved\", simplify = FALSE)"), "[Eq(Integral(1/sqrt(-2*_u*asin(_u) + C1 - 2*sqrt(1 - _u^2)), (_u, f(x))), C2 + x), Eq(Integral(1/sqrt(-2*_u*asin(_u) + C1 - 2*sqrt(1 - _u^2)), (_u, f(x))), C2 - x)]")
})

