  expect_equal(.odetest("classify_ode((Integer(1) + (Integer(2)*Symbol(\"x\")*(Function(\"f\")(Symbol(\"x\")))^(Integer(2))) + (Symbol(\"x\")*Derivative(Function(\"f\")(Symbol(\"x\")), Symbol(\"x\"))*Function(\"f\")(Symbol(\"x\")))), Function(\"f\")(Symbol(\"x\")))"), "('1st_exact', 'Bernoulli', 'almost_linear', 'lie_group', '1st_exact_Integral', 'Bernoulli_Integral', 'almost_linear_Integral')")
